<script setup>
import {onMounted,onUnmounted} from 'vue'
import {createKnowledgeRelease,armLabel,directionLabel} from './useKnowledgeRelease.js'
const props=defineProps({developer:Boolean})
const ctl=createKnowledgeRelease(),{data,comparison,error,busy}=ctl
onMounted(ctl.load);onUnmounted(ctl.dispose)
const name=s=>({'000333.SZ':'美的集团','600036.SH':'招商银行'})[s]||s
const route=s=>({TREND_SWING:'趋势波段',QUALITY_GROWTH:'质量成长'})[s]||'无路线定义'
</script>
<template><section class="panel rep-section knowledge-release"><div class="section-heading"><h2>投资计划与知识体系交付</h2><button class="btn" :disabled="busy" @click="ctl.load">刷新交付记录</button></div><p v-if="error" role="alert" class="error-text">{{ error }}</p><p v-if="busy" role="status">正在核对封存交付记录…</p><p v-if="data?.status==='NOT_PUBLISHED'" class="muted">统一验证正在进行，完成后展示真实交付记录。</p>
